package ru.folio.notes;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import java.io.*;
import java.util.*;

/** Native selection/rendering tests with temporary preferences and an unsaved canvas. */
public final class RadialOrderTests extends Instrumentation {
    MainActivity a;SharedPreferences oldPrefs;Ink.Doc oldDoc;NotesView oldCanvas;GestureActions oldActions;String oldTab;int checks;
    void check(boolean yes,String text){if(!yes)throw new AssertionError(text);checks++;}
    void main(Runnable r)throws Exception{Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new RuntimeException(error[0]);}
    ArrayList<String> row(){ArrayList<String> names=new ArrayList<>();check(a.tools.getChildAt(0).getContentDescription().toString().equals("Навигация"),"navigation is first on toolbar");names.add("hand");for(int i=0;i<a.tools.getChildCount();i++)if(a.tools.getChildAt(i) instanceof ToolArt.Tile)names.add(((ToolArt.Tile)a.tools.getChildAt(i)).tool);return names;}
    void select(float x,float y){MotionEvent e=MotionEvent.obtain(SystemClock.uptimeMillis(),SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y,0);a.canvas.paletteTouch(e);e.recycle();}
    void sector(int slot){NotesView v=a.canvas;select(v.radialX+RadialPalette.x(slot,78)*v.dp(1),v.radialY+RadialPalette.y(slot,78)*v.dp(1));}
    void draw(){NotesView v=a.canvas;Bitmap bitmap=Bitmap.createBitmap(800,800,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);c.translate(400-v.radialX,400-v.radialY);v.drawRadial(c);for(int i=0;i<8;i++)check(v.radialTools[i]==null?v.radialPainter.icons[i]==null:v.radialPainter.keys[i]!=null&&v.radialPainter.keys[i].startsWith(v.radialTools[i]),"rendered icon and touch slot agree "+i);bitmap.recycle();}
    void order(String... names){SharedPreferences.Editor editor=a.prefs.edit().putString("tool_order",String.join(",",names));for(String name:Ink.TOOLS)editor.putBoolean("tool_visible_"+name,Arrays.asList(names).contains(name));editor.apply();a.refreshTools();}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){Bundle result=new Bundle();String error=null;try{
        a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<100&&(!a.ready||a.launch!=null);i++)SystemClock.sleep(40);check(a.ready,"activity ready");
        main(()->{a.flushToolUpdates();oldPrefs=a.prefs;oldDoc=a.current;oldCanvas=a.canvas;oldActions=a.actions;oldTab=a.toolsTab;a.prefs=a.getSharedPreferences("folio-radial-order-qa",0);a.prefs.edit().clear().putBoolean(Onboarding.SEEN,true).putBoolean("toolbar_motion",false).putBoolean("backup_auto",false).putInt("squeezeBindingsVersion",1).commit();a.actions=new GestureActions(a);a.current=new Ink.Doc();a.current.title="Порядок инструментов";a.canvas=null;a.toolsTab="ink";a.buildEditor();});SystemClock.sleep(300);
        main(()->{NotesView v=a.canvas;check(row().equals(Arrays.asList(v.radialTools)),"default circle matches actual toolbar left to right");v.showPalette();check(v.radialOrder.pages()==1&&v.radialProgress==1,"default set fits one full ring");draw();sector(2);check(v.tool.equals("fountain")&&!v.radial,"touch selects fountain from new position");order("laser","tape","pen","eraser","marker","brush","pencil","lasso","fountain","text","rainbow");check(v.radialOrder.pages()==2,"all toolbar tools remain reachable over two pages");ArrayList<String> displayed=row(),circle=new ArrayList<>();v.showPalette();for(int page=0;page<v.radialOrder.pages();page++){draw();for(String name:v.radialTools)if(name!=null)circle.add(name);if(page+1<v.radialOrder.pages()){v.hoverPalette(v.radialX,v.radialY);check(v.paletteState.hovered==-1,"page control is not an out-of-range hover target");select(v.radialX,v.radialY);check(v.radial,"changing page keeps circle open");}}check(circle.equals(displayed),"every custom tool follows actual toolbar order without truncation");check(v.radialTools[4]==null&&v.paletteHit(v.radialX+RadialPalette.x(4,78)*v.dp(1),v.radialY+RadialPalette.y(4,78)*v.dp(1))==-1,"empty final-page sectors cannot select a hidden tool");v.radialPainter.lowMemory=true;v.nextPalettePage();v.radialPainter.prepare(v,v.dp(1));for(int i=0;i<8;i++)check(v.radialPainter.icons[i]==null||v.radialTools[i]!=null&&v.radialPainter.keys[i].startsWith(v.radialTools[i]),"low-memory page never draws previous tool icon");v.radialPainter.clear();v.nextPalettePage();draw();a.refreshTools();check(v.radial&&v.radialOrder.page==1,"unrelated toolbar refresh retains open page");sector(1);check(v.tool.equals("fountain"),"selection on second page uses displayed tool");v.showPalette();check(v.radialOrder.page==0,"reopening starts at beginning of toolbar");select(v.radialX,v.radialY);select(v.radialX,v.radialY);check(v.radialOrder.page==0,"center control wraps to first page");order("marker","pen","eraser");check(!v.radial&&v.radialOrder.pages()==1,"editing toolbar resets page and closes stale circle");check(row().equals(Arrays.asList(v.radialTools).subList(0,4)),"reorder and hidden tools update immediately");check(!Arrays.asList(v.radialTools).contains("laser"),"removed instrument disappears from circle");v.showPalette();sector(1);check(v.tool.equals("marker"),"reordered marker is selected from matching position");order("brush","hand","pen","line","compass");check(Collections.frequency(row(),"hand")==1,"navigation is not duplicated when enabled explicitly");for(String name:v.radialTools)check(!GuideTools.auxiliary(name),"drawing aids stay outside pen ring");String[] expected=v.radialTools.clone();a.toolsTab="guides";a.refreshTools();check(Arrays.equals(expected,v.radialTools),"drawing-aid tab retains pen toolbar order");a.toolsTab="ink";a.refreshTools();a.buildEditor();check(Arrays.equals(expected,a.canvas.radialTools),"saved order survives editor recreation");});SystemClock.sleep(300);main(()->{if(a.launch!=null)a.launch.closeNow(false);a.canvas.showPalette();draw();File dir=new File(a.getExternalFilesDir(null),"qa");dir.mkdirs();Bitmap image=Bitmap.createBitmap(a.root.getWidth(),a.root.getHeight(),Bitmap.Config.ARGB_8888);a.root.draw(new Canvas(image));try(FileOutputStream out=new FileOutputStream(new File(dir,"radial-order.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException ex){throw new RuntimeException(ex);}finally{image.recycle();}a.canvas.closePalette();});
    }catch(Throwable failure){StringWriter trace=new StringWriter();failure.printStackTrace(new PrintWriter(trace));error=trace.toString();}
    finally{if(a!=null&&oldPrefs!=null)try{main(()->{a.canvas.closePalette();a.flushToolUpdates();a.ui.removeCallbacks(a.saveLater);a.ui.removeCallbacks(a.backupLater);a.prefs=oldPrefs;a.current=oldDoc;a.canvas=oldCanvas;a.actions=oldActions;a.toolsTab=oldTab;if(oldDoc==null){a.canvas=null;a.library();}else a.buildEditor();a.deleteSharedPreferences("folio-radial-order-qa");});}catch(Exception failure){error="cleanup: "+failure;}}
        result.putString("stream",(error==null?"PASS ":"FAIL ")+checks+" native radial order, selection, paging and rendering checks\n"+(error==null?"":error));finish(error==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
